#!/usr/bin/env python3
"""Build the offline German acceptance plan. All cases start unexecuted."""
from pathlib import Path
import csv, html, io, json, re, zipfile
ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'docs/testplan'
ART = ROOT / 'artifacts'
GROUPS = []
def group(code, name, pre, mapping, rows):
    cases = []
    for number, row in enumerate(rows.strip().splitlines(), 1):
        priority, title, steps, expected = row.split('|')
        cases.append(dict(id=f'{code}-{number:02}', group=name, priority=priority, title=title,
                          prerequisites=pre, steps=steps.split(' → '), expected=expected,
                          automation=mapping, status='Nicht ausgeführt', actual='', evidence=''))
    GROUPS.append(dict(code=code, name=name, pre=pre, mapping=mapping, cases=cases))

