CASES = [c for g in GROUPS for c in g['cases']]
def e(s): return html.escape(str(s), quote=True)

def csv_text(cases):
    buf=io.StringIO(newline=''); w=csv.writer(buf, delimiter=';')
    w.writerow(['ID','Bereich','Priorität','Titel','Voraussetzungen','Schritte','Erwartetes Ergebnis','Automatischer Bezug (keine Vollabdeckung)','Status','Ist-Ergebnis','Nachweis / Ticket','Variante / Umgebung','Tester','Datum'])
    for c in cases:
        w.writerow([c['id'],c['group'],c['priority'],c['title'],c['prerequisites'],' → '.join(c['steps']),c['expected'],c['automation'],c['status'],'','','','',''])
    return buf.getvalue()

cards=[]
for g in GROUPS:
    cards.append(f'<section class="suite" id="{g["code"]}"><div class="suite-head"><span class="eyebrow">{g["code"]} · {len(g["cases"])} Fälle</span><h2>{e(g["name"])}</h2><p><b>Voraussetzungen:</b> {e(g["pre"])}</p><p class="muted">Automatischer Bezug: {e(g["mapping"])}. Thematische Zuordnung, kein Nachweis vollständiger Testabdeckung.</p></div>')
    for c in g['cases']:
        steps=''.join(f'<li>{e(s)}</li>' for s in c['steps'])
        cards.append(f'''<details class="case" id="{c['id']}" data-priority="{c['priority']}" data-group="{g['code']}"><summary><span class="case-id">{c['id']}</span><span class="case-title">{e(c['title'])}</span><span class="priority {c['priority']}">{c['priority']}</span><span class="badge">Nicht ausgeführt</span></summary><div class="case-body"><h3>Durchführung</h3><ol>{steps}</ol><div class="expected"><h3>Erwartetes Ergebnis</h3><p>{e(c['expected'])}</p></div><div class="result"><label>Status<select data-field="status" aria-label="Status {c['id']}"><option>Nicht ausgeführt</option><option>Bestanden</option><option>Fehlgeschlagen</option><option>Blockiert</option><option>Nicht anwendbar</option></select></label><label>Variante / Umgebung<input data-field="variant" placeholder="z. B. Dropbox · SMB · X11" aria-label="Variante {c['id']}"></label><label class="wide">Ist-Ergebnis / Abweichung<textarea rows="2" data-field="actual" aria-label="Ergebnis {c['id']}" placeholder="Was wurde beobachtet? Bei N/A oder Blockiert: Begründung."></textarea></label><label class="wide">Nachweis / Ticket<input data-field="evidence" aria-label="Nachweis {c['id']}" placeholder="Screenshot-Dateiname, Logauszug ohne Geheimnisse, Issue-Link"></label></div><p class="muted">Für mehrere Provider/Varianten pro Variante einen separaten Lauf exportieren. Ein Bestanden-Eintrag gilt nur für die angegebene Variante.</p></div></details>''')
    cards.append('</section>')
nav=''.join(f'<a href="#{g["code"]}"><span>{g["code"]}</span>{e(g["name"])}</a>' for g in GROUPS)
opts=''.join(f'<option value="{g["code"]}">{e(g["name"])}</option>' for g in GROUPS)
counts={p:sum(c['priority']==p for c in CASES) for p in ['P0','P1','P2']}
intro='''<section id="vorbereitung" class="guide"><h2>So wird der Plan verwendet</h2><p><b>Dies ist ein Testplan, kein Prüfbericht.</b> Alle Fälle starten als „Nicht ausgeführt“. Historische Ergebnisse in <code>linux/TESTING.md</code> sind ein eigener Nachweis und werden hier nicht als bestanden übernommen. Der Umfang betrifft die Linux-Version; macOS-Parität ist kein automatisch bestätigtes Ergebnis.</p><ol><li>Build, Profil, Betriebssystem und Variante oben eintragen. Nur eine ausdrücklich getrennte Testinstanz mit eigenen Testdaten nutzen.</li><li>Zuerst Smoke-Test, dann P0, danach P1/P2 und die Variantenmatrix ausführen. Jeden Befund mit Ist-Ergebnis und Nachweis erfassen.</li><li>Vor einer neuen Provider-/Backendvariante den Lauf exportieren. „Neuer Lauf“ leert die Ergebnisse erst nach Bestätigung; JSON-Sicherung erlaubt spätere Wiederaufnahme.</li><li>Ein fehlendes Konto/Medium ist „Blockiert“, kein Erfolg. „Nicht anwendbar“ begründen und für die Freigabe ausdrücklich akzeptieren.</li><li>Nach Fehlerkorrektur betroffenen Fall, benachbarte Fälle und Smoke-Test erneut ausführen. Alten Export als Nachweis behalten.</li></ol><p class="notice">Keine realen laufenden Übertragungen unterbrechen. Prozessabbruch, Netzsperren, defekte Volumes und Journalmanipulation nur in der Test-VM. Cloud-Schreibtests ausschließlich in einem neu angelegten Testordner. Keine Passwörter, Tokens, privaten Schlüssel oder persönliche Dateien in Nachweisen speichern.</p><h3>Prioritäten und Freigabe</h3><p><b>P0:</b> Datenintegrität, Sicherheit, Kernabläufe und frühere schwere Fehler. <b>P1:</b> wesentliche Funktionen, Stabilität und Bedienbarkeit. <b>P2:</b> seltene Umgebungs-/Komfortvarianten. Priorität ist nicht die Fehler-Schwere.</p><p>Freigabevorschlag: Alle anwendbaren P0-Fälle in der vereinbarten Pflichtmatrix bestanden; keine offenen Datenverlust-, Sicherheits-, Crash- oder dauerhaften GUI-Blockadefehler. Alle P1/P2 bewertet, Restfehler mit Auswirkung und Verantwortlichem akzeptiert. Nicht getestete Pflichtdienste bleiben offene Freigabepunkte. Automatisierte Regression und Paket-Smoke-Test müssen zum tatsächlich geprüften Build passen.</p><h3>Fehler-Schwere</h3><p><b>S1:</b> Datenverlust/Geheimnisoffenlegung. <b>S2:</b> Crash, festgefahrene Hauptfunktion, falscher Erfolg. <b>S3:</b> Funktion gestört mit praktikablem Umweg. <b>S4:</b> kosmetisch/Text. Jeder Bericht enthält Fall-ID, Build, Variante, reproduzierbare Schritte, Soll/Ist, Häufigkeit und bereinigten Nachweis.</p></section>
<section id="daten" class="guide"><h2>Testumgebung und Datensätze</h2><p>Empfohlene Referenz: Ubuntu 24.04 x86_64 mit GNOME; zusätzlich X11 und Wayland soweit verfügbar. Andere Distributionen separat als Kompatibilitätslauf erfassen. Lokale ext4-Quelle, zweites Dateisystem, SMB/GVFS-NAS, USB-Testmedium und eigene Cloud-Testkonten. Browser, GIO, optional ffmpeg und Linux-Schlüsselbund mit Versionen notieren. System-rclone und von OpenCommander verwendetes rclone getrennt erfassen.</p><p>Mit <code>--state-dir /absoluter/pfad/zum/testprofil</code> eine eigene App-Konfiguration verwenden; Daten und Mounts ebenfalls trennen. Ein Testprofil isoliert nicht automatisch globale Desktop-Zuordnungen, SSH-Agent, Netzwerk oder Betriebssystem-Schlüsselbund: dafür Testkonto/VM nutzen. Vor Tests Profil und Manifest sichern.</p><div class="table-wrap"><table><thead><tr><th>Datensatz</th><th>Inhalt</th><th>Prüfung</th></tr></thead><tbody><tr><td>D1 · Funktion</td><td>Mindestens 30 synthetische Dateien; 0 Byte, 1 Byte, 1 MiB; Unicode, Leerzeichen, lange gültige Namen; versteckte Dateien, leere und verschachtelte Ordner, Symlinks; getrennte Namenskollisionen.</td><td>Manifest mit relativem Pfad, Typ, Größe und SHA-256 vor und nach Aktion. Metadaten je Backend separat beurteilen.</td></tr><tr><td>D2 · Last</td><td>20.000 kleine Dateien, eine 2-GiB-Datei und gemischter Baum von mindestens 5 GiB. Optional 100-GiB-Lauf bei genug Platz; 1.000 synthetische History-Einträge.</td><td>Zeit, Durchsatz, GUI-Latenz, CPU/RAM und Endhashes. Freier Speicher für Quelle, Ziel, Staging und Undo-Kopien vorhalten.</td></tr><tr><td>D3 · Medien</td><td>JPG/JPEG, PNG, WebP, GIF; defektes Bild, großer Decoderfall; kleines MP4 und Audio; Text/Binär; Grenzwertfälle getrennt.</td><td>Bekanntes Motiv/Inhalt, Reihenfolge, Wiedergabe, Seek, Fehlergrenzen und Temp-Bereinigung.</td></tr><tr><td>D4 · Archive</td><td>Alle angebotenen Formate mit gleichem Inhalt; leere/defekte/verschlüsselte und kontrollierte unsichere Archive.</td><td>Extraktionsmanifest; außerhalb des Testziels darf nichts entstehen. Keine enthaltene Datei ausführen.</td></tr></tbody></table></div><p><b>Rückbau:</b> Testfreigaben beim Provider widerrufen, Testaufträge geordnet beenden, ausschließlich zu diesem Lauf gehörige Testordner und Mounts entfernen; Zuordnung/VM zurücksetzen. OpenCommander-Papierkorb und Staging können Datenplatz belegen. Keine pauschale Löschung von <code>.OpenCommander*</code> auf Benutzerlaufwerken.</p></section>
<section id="matrix" class="guide"><h2>Variantenmatrix und Prüfphasen</h2><div class="table-wrap"><table><thead><tr><th>Matrix</th><th>Pflichtvarianten</th><th>Fälle / Nachweis</th></tr></thead><tbody><tr><td>C1 · Cloud</td><td>OneDrive Personal; Google Drive; Dropbox; iCloud Drive. OneDrive Business/Shared Drives zusätzlich, wenn genutzt.</td><td>AUTH + CLOUD + Online-Fälle von MEDIA/FILE/TRASH. Pro Dienst ein Export. Freigaben nur Drive/OneDrive/Dropbox; iCloud eingeschränkte Funktionen ausdrücklich prüfen.</td></tr><tr><td>T1 · Transfer</td><td>Lokal→lokal; lokal↔SMB; lokal↔jede Cloud; OneDrive→SMB; OneDrive→Drive; Drive→Dropbox. Kopieren und Verschieben getrennt.</td><td>FILE-01/02/06/07/11/12, JOB-01/06/07/08, REC-01/08, TRASH-05. Je Richtung/Operation ein Lauf; Hashvergleich unabhängig vom Dateinamen.</td></tr><tr><td>T2 · Mountmodus</td><td>App-eigene Einbindung; externer rclone-Mount mit Full-Cache/Writeback; Read-only; offline.</td><td>CLOUD-08/12, REC-05/08, DEVICE-04. Provider-Bestätigung statt nur lokaler Cacheprüfung.</td></tr><tr><td>S1 · Server</td><td>SFTP Passwort/Schlüssel/Agent; FTP; explizites FTPS; SMB; WebDAV.</td><td>SERVER und passende Transfer-/Properties-Fälle. Zertifikats- und Host-Key-Negativtests Pflicht.</td></tr><tr><td>U1 · Oberfläche</td><td>DE/EN, hell/dunkel, X11/Wayland, 100/150/200 %, Maus/Tastatur, schmale Fenster.</td><td>NAV, PLACE, PROP sowie Auftragskarten/Preview. Nicht jede Kombination blind vervielfachen: alle Werte abdecken, auffällige Kombinationen nachtesten.</td></tr></tbody></table></div><h3>Empfohlene Reihenfolge</h3><ol><li><b>Smoke · ca. 30–45 Minuten:</b> START-01, NAV-01/03/09, FILE-01/03, JOB-06/07/08, TRASH-01/04, MEDIA-01, PLACE-01/03 und PROP-04.</li><li><b>Kernfunktionen · ca. 1 Arbeitstag:</b> lokale Navigation, Dateiaktionen, Archive, Werkzeuge, Undo, Einstellungen und automatisierte Regression.</li><li><b>Provider-/Servermatrix · ca. 1–3 Arbeitstage:</b> Konten, Transfers, Vorschau, Freigaben und Netzausfälle; abhängig von Uploadrate und Kontoverfügbarkeit.</li><li><b>Recovery und Last · ca. 1–2 Arbeitstage:</b> kontrollierte Unterbrechungen, Integrität, Dauerlauf und Messungen. Große Uploads können länger dauern.</li><li><b>Nachtest/Freigabe:</b> Fehler nachprüfen, offene Matrixfelder und akzeptierte Einschränkungen dokumentieren.</li></ol><p>Aufwände sind Planungswerte für vorbereitete Testumgebungen, keine Zusage von Ausführungszeiten. Große Datentransfers und echte Provider-Läufe sind nicht durch einen kurzen Unit-Test ersetzbar.</p><h3>Messverfahren</h3><p>Kalt/warm getrennt messen; drei vergleichbare Durchläufe, Median und schlechtesten Wert notieren. GUI-Rückmeldung ab Klick per Bildschirmaufnahme messen. Sollziel für Bedienfeedback ≤ 250 ms, spätestens 1 s; langsame Netzoperationen dürfen länger laufen, müssen aber Status und Abbruch anbieten. Ein einzelner blockierter Systemaufruf kann den tatsächlichen Stopp verzögern; die GUI muss die Anforderung sofort anzeigen. Durchsatz gegen denselben Backend-/Netzaufbau vergleichen. Bei Hashkontrolle Remote-Inhalt unabhängig herunterladen/lesen; Dateigröße allein beweist keine Integrität.</p></section>'''
page=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Ausführlicher, ausfüllbarer Testplan für OpenCommander Linux 0.3.19"><title>OpenCommander · Testplan Linux 0.3.19</title><style>__CSS__</style></head><body><a class="skip" href="#inhalt">Zum Inhalt</a><header><a class="brand" href="#anfang">◈ OpenCommander <small>QUALITÄT & ABNAHME · LINUX 0.3.19</small></a><div class="actions"><button id="theme">Hell / Dunkel</button><button id="print">Drucken / PDF</button></div></header><aside><a href="#vorbereitung">Durchführung & Freigabe</a><a href="#daten">Umgebung & Testdaten</a><a href="#matrix">Varianten & Prüfphasen</a><nav>{nav}</nav></aside><main id="inhalt"><section class="hero" id="anfang"><span class="eyebrow">TESTPLAN · 12. OKTOBER 2026</span><h1>Jede Funktion.<br><em>Ein prüfbares Ergebnis.</em></h1><p>Ein ausführlicher Prüfplan für Alltag, Cloud, Datenintegrität und die Momente, in denen etwas schiefgeht.</p><div class="stats"><div><b>{len(CASES)}</b><span>konkrete Testfälle</span></div><div><b>{len(GROUPS)}</b><span>Funktionsbereiche</span></div><div><b>{counts['P0']}</b><span>kritische P0-Fälle</span></div></div><p class="hero-note">Stand: Linux 0.3.19 · Ausgangscommit 84a3365 · Alle Testfälle zunächst nicht ausgeführt. Keine Änderung an laufenden Kopieraufträgen.</p></section><section class="run guide"><h2>Dein Testlauf</h2><div class="meta"><label>Laufname<input id="runName" placeholder="z. B. Dropbox → SMB · Kopieren"></label><label>Tester<input id="tester" placeholder="Name"></label><label>Datum<input id="date" type="date"></label><label>Build / Commit<input id="build" value="0.3.19 / 84a3365"></label><label class="wide">Umgebung / Varianten / Einschränkungen<textarea id="environment" rows="2" placeholder="OS, Desktop, CPU/RAM, App-Paket, rclone, Dateisysteme, Testkonten-Alias, Netzbedingungen"></textarea></label></div><div class="actions wrap"><button id="exportCsv">Ergebnisse als CSV</button><button id="exportJson">Sicherung als JSON</button><button id="importButton">JSON wieder laden</button><input type="file" id="importJson" accept="application/json,.json" hidden><button id="newRun">Neuer Lauf</button></div><p id="saveStatus" role="status">Ergebnisse werden lokal in diesem Browser gespeichert. Für dauerhafte Sicherung und Variantenwechsel JSON/CSV exportieren; keine Cloud-Synchronisierung.</p><p id="progress" aria-live="polite"></p><div class="progress-track"><div id="progressBar"></div></div></section>{intro}<section class="guide filters" id="faelle"><h2>Testfälle bearbeiten</h2><div class="filter-row"><label>Suche<input id="search" type="search" placeholder="ID, Funktion oder Fehlertext …"></label><label>Bereich<select id="group"><option value="">Alle Bereiche</option>{opts}</select></label><label>Priorität<select id="priority"><option value="">Alle</option><option>P0</option><option>P1</option><option>P2</option></select></label><label>Status<select id="status"><option value="">Alle</option><option>Nicht ausgeführt</option><option>Bestanden</option><option>Fehlgeschlagen</option><option>Blockiert</option><option>Nicht anwendbar</option></select></label></div><div class="actions wrap"><button id="expand">Sichtbare aufklappen</button><button id="collapse">Zuklappen</button><button id="clearFilters">Filter zurücksetzen</button></div><p id="visible" role="status"></p></section><div id="cases">{''.join(cards)}</div><footer><p>OpenCommander Linux · Testplan 0.3.19 · Offline nutzbar · Quelle: Repository, Anwenderhandbuch und bestehende Testmodule.</p><p>Ein ausgefüllter Plan gilt nur für den dokumentierten Build und die tatsächlich ausgeführten Varianten. PDF-Druck enthält alle Fälle und die eingetragenen Ergebnisse.</p></footer></main><noscript><div class="notice">JavaScript ist deaktiviert. Alle Testfälle sind lesbar; automatische Speicherung, Filter und Export benötigen JavaScript. Die CSV-Vorlage ist separat beigefügt.</div></noscript><dialog id="confirmDialog"><h2>Lauf ersetzen?</h2><p id="confirmMessage"></p><div class="actions"><button id="confirmNo">Abbrechen</button><button id="confirmYes">Ersetzen</button></div></dialog><script id="planData" type="application/json">{json.dumps(CASES,ensure_ascii=False).replace('<','\\u003c')}</script><script>__JS__</script></body></html>'''

def main():
    OUT.mkdir(parents=True,exist_ok=True); ART.mkdir(parents=True,exist_ok=True)
    rendered=page.replace('__CSS__',(OUT/'testplan.css').read_text()).replace('__JS__',(OUT/'testplan.js').read_text())
    (OUT/'index.html').write_text(rendered)
    (OUT/'testfaelle.json').write_text(json.dumps(CASES,ensure_ascii=False,indent=2)+'\n')
    (OUT/'testfaelle.csv').write_text(csv_text(CASES),encoding='utf-8-sig')
    name='OpenCommander-Testplan-Linux-0.3.19'
    (ART/(name+'.html')).write_text(rendered)
    (ART/(name+'.csv')).write_text(csv_text(CASES),encoding='utf-8-sig')
    with zipfile.ZipFile(ART/(name+'.zip'),'w',zipfile.ZIP_DEFLATED) as z:
        for file in ['index.html','testfaelle.csv','testfaelle.json']:
            z.write(OUT/file,arcname=name+'/'+file)
    print(json.dumps({'cases':len(CASES),'groups':len(GROUPS),'priorities':counts},ensure_ascii=False))
if __name__=='__main__': main()
